-- Online Testing Website (MATCHED to the Muse version) — MySQL schema + demo seed
-- Schema is UNCHANGED from the original PHP ZIP (15 tables). No upgrade.sql is needed for existing installs.
-- This ZIP is matched to the Muse-hosted version; the two copies do NOT sync data.
-- Create DB first in phpMyAdmin / MySQL, or run: CREATE DATABASE online_testing CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE DATABASE IF NOT EXISTS online_testing CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE online_testing;

CREATE TABLE IF NOT EXISTS boards(id INT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(120) NOT NULL, slug VARCHAR(120) UNIQUE NOT NULL, is_demo TINYINT(1) DEFAULT 0);
CREATE TABLE IF NOT EXISTS classes(id INT AUTO_INCREMENT PRIMARY KEY, board_id INT NULL, name VARCHAR(80) NOT NULL, grade INT NOT NULL, is_demo TINYINT(1) DEFAULT 0, FOREIGN KEY(board_id) REFERENCES boards(id) ON DELETE SET NULL, INDEX(grade));
CREATE TABLE IF NOT EXISTS categories(id INT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(120) NOT NULL, slug VARCHAR(120) UNIQUE NOT NULL, is_demo TINYINT(1) DEFAULT 0);
CREATE TABLE IF NOT EXISTS subjects(id INT AUTO_INCREMENT PRIMARY KEY, category_id INT NULL, name VARCHAR(120) NOT NULL, slug VARCHAR(120) UNIQUE NOT NULL, is_demo TINYINT(1) DEFAULT 0, FOREIGN KEY(category_id) REFERENCES categories(id) ON DELETE SET NULL);
CREATE TABLE IF NOT EXISTS users(id INT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(120) NOT NULL, email VARCHAR(190) UNIQUE NOT NULL, password_hash VARCHAR(255) NOT NULL, role ENUM('student','admin') DEFAULT 'student', class_id INT NULL, created_at DATETIME DEFAULT CURRENT_TIMESTAMP, last_login DATETIME NULL, FOREIGN KEY(class_id) REFERENCES classes(id) ON DELETE SET NULL, INDEX(email));
CREATE TABLE IF NOT EXISTS tests(id INT AUTO_INCREMENT PRIMARY KEY, title VARCHAR(200) NOT NULL, slug VARCHAR(200) UNIQUE NOT NULL, class_id INT NULL, subject_id INT NULL, category_id INT NULL, chapter VARCHAR(160) DEFAULT '', difficulty ENUM('Easy','Medium','Hard') DEFAULT 'Medium', duration_minutes INT DEFAULT 20, passing_percent INT DEFAULT 40, negative_marking DECIMAL(4,2) DEFAULT 0, description TEXT, is_published TINYINT(1) DEFAULT 0, is_demo TINYINT(1) DEFAULT 0, created_by INT NULL, created_at DATETIME DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(class_id) REFERENCES classes(id) ON DELETE SET NULL, FOREIGN KEY(subject_id) REFERENCES subjects(id) ON DELETE SET NULL, FOREIGN KEY(category_id) REFERENCES categories(id) ON DELETE SET NULL, FOREIGN KEY(created_by) REFERENCES users(id) ON DELETE SET NULL, INDEX(is_published));
CREATE TABLE IF NOT EXISTS questions(id INT AUTO_INCREMENT PRIMARY KEY, test_id INT NOT NULL, question_text TEXT NOT NULL, question_type ENUM('mcq','tf') DEFAULT 'mcq', marks DECIMAL(5,2) DEFAULT 1, explanation TEXT, sort_order INT DEFAULT 0, is_demo TINYINT(1) DEFAULT 0, FOREIGN KEY(test_id) REFERENCES tests(id) ON DELETE CASCADE, INDEX(test_id));
CREATE TABLE IF NOT EXISTS options(id INT AUTO_INCREMENT PRIMARY KEY, question_id INT NOT NULL, option_text VARCHAR(500) NOT NULL, is_correct TINYINT(1) DEFAULT 0, sort_order INT DEFAULT 0, FOREIGN KEY(question_id) REFERENCES questions(id) ON DELETE CASCADE, INDEX(question_id));
CREATE TABLE IF NOT EXISTS attempts(id INT AUTO_INCREMENT PRIMARY KEY, user_id INT NOT NULL, test_id INT NOT NULL, mode ENUM('practice','exam') DEFAULT 'practice', status ENUM('in_progress','completed') DEFAULT 'in_progress', question_order TEXT, started_at DATETIME DEFAULT CURRENT_TIMESTAMP, submitted_at DATETIME NULL, obtained_marks DECIMAL(7,2) DEFAULT 0, total_marks DECIMAL(7,2) DEFAULT 0, percentage DECIMAL(5,2) DEFAULT 0, passed TINYINT(1) DEFAULT 0, UNIQUE KEY uniq_active (user_id,test_id,mode,status), FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE, FOREIGN KEY(test_id) REFERENCES tests(id) ON DELETE CASCADE, INDEX(user_id), INDEX(test_id));
CREATE TABLE IF NOT EXISTS student_answers(id INT AUTO_INCREMENT PRIMARY KEY, attempt_id INT NOT NULL, question_id INT NOT NULL, selected_option_id INT NULL, is_correct TINYINT(1) DEFAULT 0, marks_awarded DECIMAL(5,2) DEFAULT 0, marked_review TINYINT(1) DEFAULT 0, UNIQUE KEY uniq_ans (attempt_id,question_id), FOREIGN KEY(attempt_id) REFERENCES attempts(id) ON DELETE CASCADE, FOREIGN KEY(question_id) REFERENCES questions(id) ON DELETE CASCADE, FOREIGN KEY(selected_option_id) REFERENCES options(id) ON DELETE SET NULL);
CREATE TABLE IF NOT EXISTS bookmarks(id INT AUTO_INCREMENT PRIMARY KEY, user_id INT NOT NULL, question_id INT NOT NULL, created_at DATETIME DEFAULT CURRENT_TIMESTAMP, UNIQUE KEY uniq_bm (user_id,question_id), FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE, FOREIGN KEY(question_id) REFERENCES questions(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS certificates(id INT AUTO_INCREMENT PRIMARY KEY, user_id INT NOT NULL, attempt_id INT NOT NULL, code VARCHAR(40) UNIQUE NOT NULL, title VARCHAR(200) NOT NULL, issued_at DATETIME DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE, FOREIGN KEY(attempt_id) REFERENCES attempts(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS announcements(id INT AUTO_INCREMENT PRIMARY KEY, title VARCHAR(200) NOT NULL, body TEXT, is_active TINYINT(1) DEFAULT 1, created_at DATETIME DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS settings(`key` VARCHAR(80) PRIMARY KEY, value TEXT);
CREATE TABLE IF NOT EXISTS contact_messages(id INT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(120) NOT NULL, email VARCHAR(190) NOT NULL, message TEXT NOT NULL, created_at DATETIME DEFAULT CURRENT_TIMESTAMP);

