INSERT INTO settings(`key`,value) VALUES('site_name','Online Testing'),('site_tagline','Practice tests for Class 1–12 and general subjects.') ON DUPLICATE KEY UPDATE value=VALUES(value);
INSERT INTO boards(name,slug,is_demo) VALUES('General Board','general-board',1),('Punjab Board','punjab-board',1),('Federal Board','federal-board',1),('Cambridge (General)','cambridge-general',1) ON DUPLICATE KEY UPDATE name=VALUES(name), is_demo=VALUES(is_demo);
INSERT INTO classes(board_id,name,grade,is_demo) SELECT 1,CONCAT('Class ',n),n,1 FROM (SELECT 1 n UNION SELECT 2 UNION SELECT 3 UNION SELECT 4 UNION SELECT 5 UNION SELECT 6 UNION SELECT 7 UNION SELECT 8 UNION SELECT 9 UNION SELECT 10 UNION SELECT 11 UNION SELECT 12) t;
INSERT INTO categories(name,slug,is_demo) VALUES('Computer','computer',1),('General Knowledge','general-knowledge',1),('IQ and Reasoning','iq-reasoning',1),('English','english',1),('Mathematics','mathematics',1),('Science','science',1),('Urdu','urdu',1) ON DUPLICATE KEY UPDATE name=VALUES(name), is_demo=VALUES(is_demo);
INSERT INTO subjects(category_id,name,slug,is_demo) VALUES(1,'Computer Science','computer-science',1),(2,'General Knowledge','general-knowledge',1),(3,'IQ and Reasoning','iq-reasoning',1),(4,'English','english',1),(5,'Mathematics','mathematics',1),(6,'Science','science',1),(7,'Urdu','urdu',1) ON DUPLICATE KEY UPDATE category_id=VALUES(category_id), name=VALUES(name), is_demo=VALUES(is_demo);
